<section class="admin-content"><div class="admin-heading"><div><div class="eyebrow">محتوای صفحه اصلی</div><h1>مدیریت بنرها</h1><p class="muted">بنرهای Hero صفحه اصلی را بدون تغییر کد مدیریت کنید.</p></div></div><?php if($m=Session::flash('success')):?><div class="alert success">✅ <?=e($m)?></div><?php endif;?><div class="admin-panel"><h2>افزودن بنر</h2><form class="banner-admin-form" method="post" action="<?=url('/admin/banners')?>"><?=csrf_field()?><input name="title" required placeholder="عنوان اصلی بنر"><textarea name="subtitle" placeholder="توضیح کوتاه"></textarea><input name="cta_text" placeholder="متن دکمه"><input name="cta_url" placeholder="آدرس دکمه، مثل /jobs"><input name="image_url" placeholder="آدرس تصویر یا پس‌زمینه اختیاری"><input type="number" name="sort_order" value="0" placeholder="ترتیب"><select name="status"><option value="active">فعال</option><option value="draft">پیش‌نویس</option></select><button class="button" type="submit">ذخیره بنر</button></form></div><div class="admin-panel"><h2>بنرهای موجود</h2><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>دکمه</th><th>ترتیب</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($banners as $banner):?><tr><td><strong><?=e($banner['title'])?></strong><small><?=e($banner['subtitle']??'')?></small></td><td><?=e($banner['cta_text']??'—')?></td><td><?=e($banner['sort_order'])?></td><td><span class="status status-<?=e($banner['status'])?>"><?=e($banner['status'])?></span></td><td><form method="post" action="<?=url('/admin/banners/status')?>"><?=csrf_field()?><input type="hidden" name="banner_id" value="<?=e($banner['id'])?>"><input type="hidden" name="status" value="<?=$banner['status']==='active'?'draft':'active'?>"><button class="action-button" type="submit"><?=$banner['status']==='active'?'غیرفعال کردن':'فعال کردن'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></section>